"""35 - splice the payloads and the shared core into the page templates.

The pages are self-contained: every byte of data they show is IN the file, because they open
from file:// with no server and a page cannot fetch beside itself there. The templates live in
scripts/dashboard/ (one copy for every organism group) and carry four kinds of marker:

    <!--CORE:css-->                  THEME_INIT (applies a saved light theme before first paint),
                                     then the shared stylesheet, scripts/dashboard/core.css
    <!--CORE:js-->                   the codec generated by 30_dashboard_common.js_decoder(),
                                     a META object, then scripts/dashboard/core.js
    <!--DATA:__NAME:file.json-->     <script>window.__NAME={...}</script> from <group>/Dashboard/
    <!--GROUP_NAME-->                the organism group, for titles

Editing a page means editing the template, never the built file: a built page is one multi-megabyte
line and a hand edit to it is lost on the next build. Modelled on the ArchaeaHQ dashboard's
23_build_pages.py.

Usage: python3 scripts/35_build_pages.py [--group G]
"""
import importlib.util
import json
import os
import re
import sys
import time
from pathlib import Path

from amr_common import DASHBOARD, GROUP, CLUSTER_PREFIX

_spec = importlib.util.spec_from_file_location(
    "dash", os.path.join(os.path.dirname(os.path.abspath(__file__)), "30_dashboard_common.py"))
dash = importlib.util.module_from_spec(_spec)
_spec.loader.exec_module(dash)

SRC = Path(__file__).resolve().parent / "dashboard"
PAGES = [("islands_template.html", "islands.html"),
         ("clusters_template.html", "clusters.html"),
         ("antibiograms_template.html", "antibiograms.html")]
STALE = ["structures.html"]        # pages that used to be built; removed so no old copy lingers
MARK = re.compile(r"<!--DATA:(__\w+):([\w.\-]+)-->")
# runs in <head>, before anything is drawn; the key and the button are in core.js
THEME_INIT = ("<script>try{if(localStorage.getItem(\"amr-dashboard-theme\")===\"light\")"
              "document.documentElement.dataset.theme=\"light\"}catch(e){}</script>")


def core_js():
    meta = {"group": GROUP, "prefix": CLUSTER_PREFIX, "islandPrefix": dash.ISLAND_PREFIX,
            "built": time.strftime("%Y-%m-%d")}
    return (dash.js_decoder() + "\nconst META=" + json.dumps(meta) + ";\n"
            + (SRC / "core.js").read_text(encoding="utf-8"))


def main():
    css = THEME_INIT + "\n<style>\n" + (SRC / "core.css").read_text(encoding="utf-8") + "</style>"
    js = "<script>\n" + core_js() + "\n</script>"
    group_name = GROUP.replace("_", " ")
    built = []
    for tpl, out in PAGES:
        path = SRC / tpl
        if not path.exists():
            raise SystemExit(f"[35] template missing: {path}")
        s = path.read_text(encoding="utf-8")
        missing = []

        def sub(m):
            var, fn = m.group(1), m.group(2)
            f = DASHBOARD / fn
            if not f.exists():
                missing.append(fn)
                return m.group(0)
            return f"<script>window.{var}=" + f.read_text(encoding="utf-8").rstrip() + "</script>"

        s = MARK.sub(sub, s)
        if missing:
            raise SystemExit(f"[35] {tpl} needs payloads that do not exist: {', '.join(missing)} "
                             f"- run scripts 31-34 first")
        for marker in ("<!--CORE:css-->", "<!--CORE:js-->"):
            if marker not in s:
                raise SystemExit(f"[35] {tpl} has no {marker} marker")
        s = s.replace("<!--CORE:css-->", css).replace("<!--CORE:js-->", js)
        s = s.replace("<!--GROUP_NAME-->", group_name)
        (DASHBOARD / out).write_text(s, encoding="utf-8")
        mb = (DASHBOARD / out).stat().st_size / 1e6
        built.append((out, mb))
        print(f"[35] {out}  {mb:.2f} MB  (template {path.stat().st_size / 1e3:.0f} KB)", flush=True)
    for name in STALE:
        if (DASHBOARD / name).exists():
            (DASHBOARD / name).unlink()
            print(f"[35] removed stale {name}")
    print(f"[35] {len(built)} pages in {DASHBOARD}")


if __name__ == "__main__":
    main()
